def separate_paren_groups(paren_string: str) -> List[str]:
    """ The purpose of this function is to dissect a string containing various nested parentheses groups. It extracts each group into its own string and compiles them into a list. The groups are properly balanced and not embedded within one another. Any spaces in the input string are ignored.
    >>> separate_paren_groups('( ) (( )) (( )( ))')
    ['()', '(())', '(()())']
    """
    result = []
    current_group = []
    balance = 0

    for char in paren_string:
        if char == ' ':
            continue
        if char == '(':
            balance += 1
            current_group.append(char)
        elif char == ')':
            balance -= 1
            current_group.append(char)

        if balance == 0:
            result.append(''.join(current_group))
            current_group = []

    return result",
